        buffer[0] = '\0';
        TEST_ASSERT_EQUAL_STRING("", buffer);
    } else {
        int result = stack_to_string(stack, buffer, buffer_size);
        TEST_ASSERT_NOT_EQUAL_INT(-1, result);
        TEST_ASSERT_EQUAL_STRING(expected_string, buffer);
