    {
        if (buffer_size >= 3)
        {
            strcpy(buffer, "[]");
            return 2;
        }
        return -1;
    }

    int written = 0;
    int remaining = buffer_size - 1;

    buffer[written++] = '[';
    remaining--;

    for (int i = 0; i <= ptr->top && remaining > 0; i++)
